 "content": "def transform(grid):
    """Infer the repeated row-color sequence from full-width colored row markers."""
    h, w = len(grid), len(grid[0])
    markers = []
    for r, row in enumerate(grid):
        vals = {v for v in row if v != 0}
        if len(vals) == 1 and all(v in (0, next(iter(vals))) for v in row):
            color = next(iter(vals))
            if sum(v == color for v in row) == w:
                markers.append((r, color))
    if not markers:
        return [row[:] for row in grid]
    period = len(markers)
    phase_color = {r % period: color for r, color in markers}
    # The rule is a periodic horizontal color band, indexed by row position.
    return [[phase_color[r % period]] * w for r in range(h)]
